<script setup>
import { ESPERA_FILTROS_MS } from '@/Utils/filtroUtil'
import { ref, watch, computed } from 'vue'
import { Head, Link, router } from '@inertiajs/vue3'
import Maindashboard from '@/Layouts/Maindashboard.vue'
import Multiselect from '@vueform/multiselect'
import DateRangeFilter from '@/Components/DateRangeFilter.vue'
import BotonDescargarGrafico from '@/Components/BotonDescargarGrafico.vue'
import { etiquetaVehiculo } from '@/Utils/asignacionVehiculoUtil'
import { useTemaGraficos } from '@/Composables/useTemaGraficos'
defineOptions({ layout: Maindashboard })

const props = defineProps({
    vehiculos: Array,
    tiposCombustible: Array,
    tiposVehiculo: Array,
    areas: Array,
    datosResumen: Object,
    filtros: Object,
})

const filtros = ref({
    fecha_inicio: props.filtros?.fecha_inicio ?? '',
    fecha_fin: props.filtros?.fecha_fin ?? '',
    id_vehiculo: props.filtros?.id_vehiculo ?? '',
    id_tipo_combustible: props.filtros?.id_tipo_combustible ?? '',
    id_area: props.filtros?.id_area ?? '',
    id_tipo_vehiculo: props.filtros?.id_tipo_vehiculo ?? '',
})

const vehiculoOptions = computed(() =>
    props.vehiculos.map((v) => ({
        id: v.id,
        label: etiquetaVehiculo(v),
    })),
)

let debounceTimer = null
watch(filtros, (val) => {
    clearTimeout(debounceTimer)
    debounceTimer = setTimeout(() => {
        router.get(route('cargas-combustible.reporte.index'), {
            // Sin "|| undefined": si el usuario limpia el filtro debe viajar
            // como '' explícito (no ausente), o el backend reaplicaría el
            // rango por defecto ("Este mes") al no encontrar la clave en el request.
            fecha_inicio: val.fecha_inicio,
            fecha_fin: val.fecha_fin,
            id_vehiculo: val.id_vehiculo || undefined,
            id_tipo_combustible: val.id_tipo_combustible || undefined,
            id_area: val.id_area || undefined,
            id_tipo_vehiculo: val.id_tipo_vehiculo || undefined,
        }, { preserveState: true, replace: true })
    }, ESPERA_FILTROS_MS)
}, { deep: true })

// El tipo de combustible, el área y el tipo de vehículo acotan el select de
// vehículo (1 vehículo = 1 tipo de combustible y 1 tipo de vehículo; el área
// depende de su asignación vigente en vehiculo_area). Si el vehículo elegido
// ya no aparece en el nuevo listado, se limpia la selección en vez de dejar
// un id "fantasma" filtrando el reporte.
watch(() => props.vehiculos, (nuevos) => {
    if (filtros.value.id_vehiculo && ! nuevos.some((v) => v.id === Number(filtros.value.id_vehiculo))) {
        filtros.value.id_vehiculo = ''
    }
})

function clearFilters() {
    filtros.value = {
        fecha_inicio: '',
        fecha_fin: '',
        id_vehiculo: '',
        id_tipo_combustible: '',
        id_area: '',
        id_tipo_vehiculo: '',
    }
}

function generarReporte() {
    if (!filtros.value.fecha_inicio || !filtros.value.fecha_fin) {
        alert('Por favor, selecciona un rango de fechas')
        return
    }

    // Genera la URL completa con sus parámetros
    const url = route('cargas-combustible.reporte.pdf', {
        fecha_inicio: filtros.value.fecha_inicio,
        fecha_fin: filtros.value.fecha_fin,
        id_vehiculo: filtros.value.id_vehiculo || null,
        id_tipo_vehiculo: filtros.value.id_tipo_vehiculo || null,
    })

    // Abre la URL en una nueva pestaña
    window.open(url, '_blank')
}

/**
 * Mismo reporte que generarReporte(), en Excel. La descarga viaja como
 * adjunto (Content-Disposition: attachment), así que se navega a la URL en
 * vez de abrir una pestaña: el navegador descarga el archivo sin salir de
 * la página actual.
 */
function generarExcel() {
    if (!filtros.value.fecha_inicio || !filtros.value.fecha_fin) {
        alert('Por favor, selecciona un rango de fechas')
        return
    }

    window.location.href = route('cargas-combustible.reporte.excel', {
        fecha_inicio: filtros.value.fecha_inicio,
        fecha_fin: filtros.value.fecha_fin,
        id_vehiculo: filtros.value.id_vehiculo || null,
        id_tipo_vehiculo: filtros.value.id_tipo_vehiculo || null,
    })
}

const totalVehiculos = computed(() => {
    return props.datosResumen?.vehiculos?.length || 0
})

const costoPorLitro = computed(() => {
    const total = props.datosResumen?.total_litros || 0
    const costo = props.datosResumen?.total_costo || 0
    return total > 0 ? (costo / total).toFixed(2) : 0
})

/* ------------------------------------------------------------------ */
/*  Gráficos comparativos (todo desde datosResumen, sin pedir nada    */
/*  más al backend)                                                    */
/* ------------------------------------------------------------------ */
const { paleta } = useTemaGraficos()

const num = (v) => Number(v ?? 0)
const bs = (v) => `Bs. ${num(v).toLocaleString('es-ES', { maximumFractionDigits: 2 })}`
const litros = (v) => `${num(v).toLocaleString('es-ES', { maximumFractionDigits: 2 })} L`

const vehiculosResumen = computed(() => props.datosResumen?.vehiculos ?? [])
const hayDatos = computed(() => vehiculosResumen.value.length > 0)

const grafBarChart = ref(null)
const grafDonutChart = ref(null)

// Bar chart: métrica seleccionable por vehículo.
const metricaVehiculo = ref('total_costo')
const METRICAS_VEHICULO = {
    total_costo: { titulo: 'Costo Total por Vehículo', serie: 'Costo (Bs.)', aditiva: true, fmt: bs },
    total_litros: { titulo: 'Litros Consumidos por Vehículo', serie: 'Litros', aditiva: true, fmt: litros },
    cantidad_cargas: { titulo: 'Cantidad de Cargas por Vehículo', serie: 'Cargas', aditiva: true, fmt: (v) => `${num(v)}` },
    precio_promedio: { titulo: 'Precio Promedio (Bs./L) por Vehículo', serie: 'Bs./L', aditiva: false, fmt: (v) => `Bs. ${num(v).toFixed(2)}` },
}

const TOPE_VEHICULOS = 15

// Ordena por la métrica y, si hay muchos vehículos, agrupa la cola en "Otros"
// (sólo para métricas que se pueden sumar).
const vehiculosGrafico = computed(() => {
    const metrica = metricaVehiculo.value
    const ordenados = [...vehiculosResumen.value].sort((a, b) => num(b[metrica]) - num(a[metrica]))

    if (ordenados.length <= TOPE_VEHICULOS) {
        return ordenados
    }

    const top = ordenados.slice(0, TOPE_VEHICULOS)

    if (! METRICAS_VEHICULO[metrica].aditiva) {
        return top
    }

    const resto = ordenados.slice(TOPE_VEHICULOS)

    return [
        ...top,
        {
            codigo: `Otros (${resto.length})`,
            nro_placa: '',
            total_costo: resto.reduce((s, v) => s + num(v.total_costo), 0),
            total_litros: resto.reduce((s, v) => s + num(v.total_litros), 0),
            cantidad_cargas: resto.reduce((s, v) => s + num(v.cantidad_cargas), 0),
        },
    ]
})

const barSeries = computed(() => [{
    name: METRICAS_VEHICULO[metricaVehiculo.value].serie,
    data: vehiculosGrafico.value.map((v) => Math.round(num(v[metricaVehiculo.value]) * 100) / 100),
}])

const barOptions = computed(() => {
    const meta = METRICAS_VEHICULO[metricaVehiculo.value]
    const horizontal = vehiculosGrafico.value.length > 6

    return {
        chart: { type: 'bar', toolbar: { show: false } },
        colors: [paleta.value[0]],
        plotOptions: { bar: { horizontal, borderRadius: 4, columnWidth: '55%', barHeight: '65%' } },
        dataLabels: {
            enabled: vehiculosGrafico.value.length <= 12,
            formatter: (v) => meta.fmt(v),
            offsetY: horizontal ? 0 : -18,
            offsetX: horizontal ? 0 : 0,
            style: { fontSize: '10px' },
        },
        xaxis: { categories: vehiculosGrafico.value.map((v) => v.codigo || v.nro_placa || '—') },
        yaxis: { title: { text: horizontal ? '' : meta.serie } },
        tooltip: { y: { formatter: (v) => meta.fmt(v) } },
        grid: { strokeDashArray: 4 },
        legend: { show: false },
    }
})

// Donut: reparto del gasto total por tipo de combustible.
const gastoPorCombustible = computed(() => {
    const acumulado = {}

    for (const v of vehiculosResumen.value) {
        const tipo = v.tipo_combustible || 'Sin tipo'
        acumulado[tipo] = (acumulado[tipo] ?? 0) + num(v.total_costo)
    }

    return {
        labels: Object.keys(acumulado),
        series: Object.values(acumulado).map((x) => Math.round(x * 100) / 100),
    }
})

const mostrarDonut = computed(() => gastoPorCombustible.value.labels.length > 1)

const donutOptions = computed(() => ({
    chart: { type: 'donut', toolbar: { show: false } },
    labels: gastoPorCombustible.value.labels,
    colors: paleta.value,
    legend: { position: 'bottom' },
    dataLabels: { enabled: true, formatter: (val) => `${Number(val).toFixed(1)}%` },
    plotOptions: { pie: { donut: { size: '62%' } } },
    tooltip: { y: { formatter: (v) => bs(v) } },
    stroke: { width: 2 },
}))
</script>

<template>
    <Head title="Reporte de Cargas de Combustible" />
        <!-- Breadcrumb -->
        <div class="d-flex align-items-center justify-content-between page-header-breadcrumb flex-wrap gap-2 mb-4">
            <div>
                <nav>
                    <ol class="breadcrumb mb-1">
                        <li class="breadcrumb-item"><Link :href="route('dashboard')">Inicio</Link></li>
                        <li class="breadcrumb-item active">Reportes</li>
                        <li class="breadcrumb-item active">Cargas de Combustible</li>
                    </ol>
                </nav>
                <h1 class="page-title fw-medium fs-18 mb-0">Reporte de Cargas de Combustible</h1>
            </div>
        </div>

        <!-- Filtros -->
        <div class="card custom-card mb-4">
            <div class="card-header"><div class="card-title">Filtros de Búsqueda</div></div>
            <div class="card-body">
                <div class="row g-3">
                    <div class="col-sm-6 col-lg-3">
                        <DateRangeFilter v-model:fecha-desde="filtros.fecha_inicio"
                            v-model:fecha-hasta="filtros.fecha_fin" label="Rango de fechas" default-range="Este mes" />
                    </div>
                    <div class="col-sm-6 col-lg-3">
                        <label class="form-label">Tipo de Combustible</label>
                        <select v-model="filtros.id_tipo_combustible" class="form-select">
                            <option value="">Todos</option>
                            <option v-for="t in tiposCombustible" :key="t.id" :value="t.id">{{ t.tipo_combustible }}</option>
                        </select>
                    </div>
                    <div class="col-sm-6 col-lg-3">
                        <label class="form-label">Área</label>
                        <select v-model="filtros.id_area" class="form-select">
                            <option value="">Todas</option>
                            <option v-for="a in areas" :key="a.id" :value="a.id">{{ a.nombre_area }}</option>
                        </select>
                    </div>
                    <div class="col-sm-6 col-lg-3">
                        <label class="form-label">Tipo de Vehículo</label>
                        <select v-model="filtros.id_tipo_vehiculo" class="form-select">
                            <option value="">Todos</option>
                            <option v-for="tv in tiposVehiculo" :key="tv.id" :value="tv.id">{{ tv.tipo_vehiculo }}</option>
                        </select>
                    </div>
                    <div class="col-lg-9">
                        <label class="form-label">Vehículo (Opcional)</label>
                        <Multiselect
                            v-model="filtros.id_vehiculo"
                            :options="vehiculoOptions"
                            value-prop="id"
                            label="label"
                            :searchable="true"
                            :filter-results="true"
                            placeholder="Todos los vehículos"
                            no-options-text="Sin vehículos"
                            no-results-text="Sin resultados"
                        />
                    </div>
                    <div class="col-lg-3 d-flex align-items-end gap-2">
                        <button type="button" class="btn btn-outline-secondary btn-wave flex-grow-1" @click="clearFilters">
                            <i class="ri-refresh-line me-1"></i> Limpiar
                        </button>
                        <button v-can="'cargas-combustible.reporte.pdf'" type="button" class="btn btn-primary btn-wave flex-grow-1" @click="generarReporte">
                            <i class="ri-file-pdf-line me-1"></i> PDF
                        </button>
                        <button v-can="'cargas-combustible.reporte.excel'" type="button" class="btn btn-success btn-wave flex-grow-1" @click="generarExcel">
                            <i class="ri-file-excel-2-line me-1"></i> Excel
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <!-- Tarjetas de Resumen -->
        <div class="row g-3 mb-4">
            <div class="col-md-3">
                <div class="card custom-card">
                    <div class="card-body">
                        <div class="d-flex align-items-center justify-content-between">
                            <div>
                                <p class="text-muted mb-1">Total de Litros</p>
                                <h3 class="fw-bold mb-0">{{ datosResumen?.total_litros?.toLocaleString() }} L</h3>
                            </div>
                            <div class="avatar avatar-lg bg-info-transparent">
                                <i class="ri-water-flash-line fs-24 text-info"></i>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="col-md-3">
                <div class="card custom-card">
                    <div class="card-body">
                        <div class="d-flex align-items-center justify-content-between">
                            <div>
                                <p class="text-muted mb-1">Total Gastado</p>
                                <h3 class="fw-bold mb-0">Bs. {{ datosResumen?.total_costo?.toLocaleString('es-ES', { maximumFractionDigits: 2 }) }}</h3>
                            </div>
                            <div class="avatar avatar-lg bg-success-transparent">
                                <i class="ri-money-dollar-circle-line fs-24 text-success"></i>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="col-md-3">
                <div class="card custom-card">
                    <div class="card-body">
                        <div class="d-flex align-items-center justify-content-between">
                            <div>
                                <p class="text-muted mb-1">Costo por Litro</p>
                                <h3 class="fw-bold mb-0">Bs. {{ costoPorLitro }}</h3>
                            </div>
                            <div class="avatar avatar-lg bg-primary-transparent">
                                <i class="ri-calculator-line fs-24 text-primary"></i>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="col-md-3">
                <div class="card custom-card">
                    <div class="card-body">
                        <div class="d-flex align-items-center justify-content-between">
                            <div>
                                <p class="text-muted mb-1">Vehículos</p>
                                <h3 class="fw-bold mb-0">{{ totalVehiculos }}</h3>
                            </div>
                            <div class="avatar avatar-lg bg-warning-transparent">
                                <i class="ri-car-line fs-24 text-warning"></i>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- Gráficos comparativos -->
        <div v-if="hayDatos" class="row g-3 mb-4">
            <div :class="mostrarDonut ? 'col-xl-8' : 'col-12'">
                <div class="card custom-card h-100">
                    <div class="card-header justify-content-between flex-wrap gap-2">
                        <div class="card-title">{{ METRICAS_VEHICULO[metricaVehiculo].titulo }}</div>
                        <div class="d-flex align-items-center gap-2">
                            <select v-model="metricaVehiculo" class="form-select form-select-sm" style="width: auto;">
                                <option value="total_costo">Costo (Bs.)</option>
                                <option value="total_litros">Litros</option>
                                <option value="cantidad_cargas">Cantidad de cargas</option>
                                <option value="precio_promedio">Precio promedio</option>
                            </select>
                            <BotonDescargarGrafico :grafico="grafBarChart" :nombre="`cargas-combustible-${metricaVehiculo}`"
                                :titulo="METRICAS_VEHICULO[metricaVehiculo].titulo" subtitulo="Reporte de Cargas de Combustible" />
                        </div>
                    </div>
                    <div class="card-body">
                        <Apexchart ref="grafBarChart" type="bar" height="360" :options="barOptions" :series="barSeries" />
                    </div>
                </div>
            </div>
            <div v-if="mostrarDonut" class="col-xl-4">
                <div class="card custom-card h-100">
                    <div class="card-header justify-content-between">
                        <div class="card-title">Gasto por Tipo de Combustible</div>
                        <BotonDescargarGrafico :grafico="grafDonutChart" nombre="cargas-combustible-por-tipo"
                            titulo="Gasto por Tipo de Combustible" subtitulo="Reporte de Cargas de Combustible" />
                    </div>
                    <div class="card-body d-flex justify-content-center">
                        <div style="width: 100%; max-width: 320px;">
                            <Apexchart ref="grafDonutChart" type="donut" height="320" :options="donutOptions" :series="gastoPorCombustible.series" />
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- Tabla de Detalle por Vehículo -->
        <div class="card custom-card">
            <div class="card-header d-flex align-items-center justify-content-between">
                <div class="card-title">
                    Detalle por Vehículo
                    <span class="badge bg-primary-transparent text-primary ms-2">{{ datosResumen?.vehiculos?.length ?? 0 }} vehículos</span>
                </div>
            </div>
            <div class="card-body p-0">
                <div class="table-responsive">
                    <table class="table table-hover text-nowrap mb-0">
                        <thead class="table-light">
                            <tr>
                                <th>#</th>
                                <th>Placa</th>
                                <th>Marca</th>
                                <th>Código</th>
                                <th>Combustible</th>
                                <th>Total Litros</th>
                                <th>Total Costo</th>
                                <th>Cantidad Cargas</th>
                                <th>Precio Promedio</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-if="!datosResumen?.vehiculos || datosResumen.vehiculos.length === 0">
                                <td colspan="9" class="text-center py-4 text-muted">
                                    <i class="ri-oil-line fs-3 d-block mb-2"></i>
                                    No se encontraron registros de combustible
                                </td>
                            </tr>
                            <tr v-for="(v, idx) in datosResumen?.vehiculos" :key="v.id_vehiculo">
                                <td>{{ idx + 1 }}</td>
                                <td class="fw-medium">{{ v.nro_placa ?? "" }}</td>
                                <td>{{ v.marca }}</td>
                                <td><span class="badge bg-secondary-transparent text-secondary">{{ v.codigo }}</span></td>
                                <td><span class="badge bg-warning-transparent text-warning">{{ v.tipo_combustible }}</span></td>
                                <td class="text-end fw-medium">{{ v.total_litros.toLocaleString() }} L</td>
                                <td class="text-end">Bs. {{ v.total_costo.toLocaleString('es-ES', { maximumFractionDigits: 2 }) }}</td>
                                <td class="text-center"><span class="badge bg-info-transparent text-info">{{ v.cantidad_cargas }}</span></td>
                                <td class="text-end">Bs. {{ v.precio_promedio }}</td>
                            </tr>
                            <!-- Fila de totales -->
                            <tr class="table-active fw-bold">
                                <td colspan="5">TOTALES</td>
                                <td class="text-end">{{ datosResumen?.total_litros?.toLocaleString() }} L</td>
                                <td class="text-end">Bs. {{ datosResumen?.total_costo?.toLocaleString('es-ES', { maximumFractionDigits: 2 }) }}</td>
                                <td class="text-center">{{ datosResumen?.cantidad_cargas }}</td>
                                <td class="text-end">Bs. {{ costoPorLitro }}</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
</template>
